package com.yihe.framework.ehr;
import java.util.*;import java.time.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
@Service @SuppressWarnings("unchecked") public class PsychologicalAssessmentService {
 final EhrRepository db;final EhrService ehr;final EmployeeHealthArchiveService employees;final DigitalWorkerModelClient client;final DigitalWorkerSettings settings;
 static final List<String> FACTORS=Arrays.asList("stress","sleep","anxiety","depression","wellbeing");
 public PsychologicalAssessmentService(EhrRepository db,EhrService ehr,EmployeeHealthArchiveService employees,DigitalWorkerModelClient client){this.db=db;this.ehr=ehr;this.employees=employees;this.client=client;this.settings=new DigitalWorkerSettings(db);}
 void allow(EhrActor a,boolean write){require(!a.mobile&&a.doctor,403,"心理测评资料仅供当前单位授权医生访问");}
 Object canonical(Object o){if(o instanceof Map){Map<String,Object> m=new TreeMap<>();((Map<?,?>)o).forEach((k,v)->m.put(String.valueOf(k),canonical(v)));return m;}if(o instanceof List){List<Object> l=new ArrayList<>();for(Object v:(List<?>)o)l.add(canonical(v));return l;}return o;}
 String hash(Object o){return hex(digest(bytes(ehr.encode(canonical(o)))));}
 int year(Object raw){int y;try{y=Integer.parseInt(str(raw));}catch(Exception e){throw new EhrException(422,"请选择有效评估年度");}require(y>=2000&&y<=LocalDate.now().getYear()+1,422,"评估年度超出范围");return y;}
 Map<String,Object> defaults(){return map("keywords",map("stress",Arrays.asList("压力"),"sleep",Arrays.asList("睡眠"),"anxiety",Arrays.asList("焦虑"),"depression",Arrays.asList("抑郁"),"wellbeing",Arrays.asList("心理测评")),"instructions","仅依据有来源的心理测评记录和明确量表名称、版本、总分及记录说明，梳理供专业人员审核的关注线索。不得从身体体检、岗位或年龄推断心理障碍，不自动确定风险等级，不诊断或推荐用药。","method","clinician_confirmed");}
 public Map<String,Object> rules(EhrActor a){allow(a,false);Map<String,Object> row=db.one("SELECT * FROM a_psych_assessment_rules WHERE scope_code=? AND data_mode=?",a.scope,a.mode);return map("document",row==null?defaults():ehr.decode(row.get("rules_json")),"version",row==null?0:row.get("row_version"),"updatedAt",row==null?null:row.get("updated_at"),"updatedBy",row==null?null:row.get("updated_by"),"canConfigure",a.doctor);}
 @Transactional public Object saveRules(EhrActor a,Map<String,Object> b){allow(a,true);Map<String,Object> doc=map("method","clinician_confirmed");Object raw=b.get("keywords");require(raw instanceof Map&&((Map<?,?>)raw).keySet().equals(new HashSet<>(FACTORS)),422,"需提供五类指标关联关键词");Map<String,Object> keywords=new LinkedHashMap<>();for(String f:FACTORS){Object list=((Map<?,?>)raw).get(f);require(list instanceof List&&((List<?>)list).size()>=1&&((List<?>)list).size()<=20,422,"每类应有1至20个关键词");List<String> words=new ArrayList<>();for(Object v:(List<?>)list){require(v instanceof String&&!str(v).trim().isEmpty()&&str(v).length()<=30,422,"关键词长度应为1至30字");words.add(str(v).trim());}keywords.put(f,words);}String instructions=text(b,"instructions").trim();require(!instructions.isEmpty()&&instructions.length()<=2000,422,"评估要求应为1至2000字");doc.put("keywords",keywords);doc.put("instructions",instructions);db.exec("INSERT IGNORE INTO a_psych_assessment_rules(scope_code,data_mode,rules_json,row_version,updated_by,updated_at) VALUES(?,?,?,0,?,UTC_TIMESTAMP(6))",a.scope,a.mode,ehr.encode(defaults()),a.user);Map<String,Object> old=db.one("SELECT row_version FROM a_psych_assessment_rules WHERE scope_code=? AND data_mode=? FOR UPDATE",a.scope,a.mode);require(b.get("version") instanceof Number&&num(b.get("version"))==num(old.get("row_version")),409,"规则已更新，请刷新后再保存");db.exec("UPDATE a_psych_assessment_rules SET rules_json=?,row_version=row_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE scope_code=? AND data_mode=?",ehr.encode(doc),a.user,a.scope,a.mode);ehr.audit(a,null,null,null,"psych_assessment_rules_saved","更新指标关联关键词和分析要求；风险等级仍须医生核定");return rules(a);}
 Map<String,Object> source(EhrActor a,String record){ehr.profile(a,record,false);Map<String,Object> p=db.one(ehr.projection()+" AND r.record_id=?",a.scope,a.mode,record);p.put("reports",new ArrayList<>());p.put("measurements",db.all("SELECT * FROM a_psych_measurements WHERE scope_code=? AND data_mode=? AND record_id=? ORDER BY measured_at,measurement_id",a.scope,a.mode,record));return new AssessmentRuleRuntime(db,ehr).attach(a,"psychological",p);}
 String sourceHash(Map<String,Object>p){Map<String,Object> person=new TreeMap<>();for(String k:Arrays.asList("id","name","code","sex","birth","age","org","team","job","rowVersion"))person.put(k,p.get(k));Map<String,Object> signature=map("person",person,"measurements",p.get("measurements"));if(p.containsKey("assessmentRules"))signature.put("assessmentRules",p.get("assessmentRules"));return hash(signature);}
 String manifest(EhrActor a,String record){return str(db.one("SELECT CONCAT(COUNT(*),':',COALESCE(MAX(measurement_id),'')) manifest FROM a_psych_measurements WHERE scope_code=? AND data_mode=? AND record_id=?",a.scope,a.mode,record).get("manifest"));}
 List<String> exposures(String text,Map<String,Object> rules){List<String> factors=new ArrayList<>();Map<String,Object> keywords=(Map<String,Object>)rules.get("keywords");for(String f:FACTORS)for(Object word:(List<?>)keywords.get(f))if(text.contains(str(word))){factors.add(f);break;}return factors;}
 String state(Map<String,Object> r){if(r.get("taskId")==null)return "not_started";if(Boolean.TRUE.equals(r.get("stale")))return "stale";if("confirmed".equals(r.get("reviewState")))return "confirmed";if("completed".equals(r.get("aiState")))return "pending_review";return str(r.get("aiState"));}
 List<Map<String,Object>> rows(EhrActor a,int year){List<Map<String,Object>> rows=db.all("SELECT r.record_id id,p.employee_name name,p.employee_no code,p.organization_name organization,p.team_name team,p.position_name job,p.exposure_history exposure,p.row_version profileVersion,t.task_id taskId,t.assessment_year assessmentYear,t.ai_state aiState,t.review_state reviewState,t.risk_level storedRisk,t.domain_json domainJson,t.profile_version sourceVersion,t.report_manifest sourceManifest,t.rules_version rulesVersion,JSON_UNQUOTE(JSON_EXTRACT(t.source_json,'$.assessmentRuleDigest')) registryDigest,t.reviewed_at reviewedAt,t.created_at createdAt,t.row_version version,(SELECT CONCAT(COUNT(*),':',COALESCE(MAX(m.measurement_id),'')) FROM a_psych_measurements m WHERE m.scope_code=r.scope_code AND m.data_mode=r.data_mode AND m.record_id=r.record_id) currentManifest FROM a_health_records r JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode LEFT JOIN a_psych_assessment_tasks t ON t.scope_code=r.scope_code AND t.data_mode=r.data_mode AND t.record_id=r.record_id AND (?=0 OR t.assessment_year=?) AND t.task_id=(SELECT t2.task_id FROM a_psych_assessment_tasks t2 WHERE t2.scope_code=r.scope_code AND t2.data_mode=r.data_mode AND t2.record_id=r.record_id AND (?=0 OR t2.assessment_year=?) ORDER BY t2.created_at DESC,t2.task_id DESC LIMIT 1) WHERE r.scope_code=? AND r.data_mode=? AND p.deleted_at IS NULL ORDER BY p.created_at,r.record_id",year,year,year,year,a.scope,a.mode);Map<String,Object> rule=rules(a);String registryDigest=new AssessmentRuleRuntime(db,ehr).digest(a,"psychological");for(Map<String,Object> r:rows){boolean stale=r.get("taskId")!=null&&(num(r.get("sourceVersion"))!=num(r.get("profileVersion"))||!str(r.get("sourceManifest")).equals(str(r.get("currentManifest")))||num(r.get("rulesVersion"))!=num(rule.get("version"))||!str(r.get("registryDigest")).equals(registryDigest));r.put("stale",stale);boolean confirmed=!stale&&"confirmed".equals(r.get("reviewState"));r.put("riskLevel",confirmed?r.get("storedRisk"):"unknown");r.put("domains",confirmed?ehr.decode(r.get("domainJson")):new HashMap<>());r.put("exposureFactors",exposures(str(r.get("exposure")),(Map<String,Object>)rule.get("document")));r.put("state",state(r));for(String k:Arrays.asList("domainJson","sourceVersion","profileVersion","sourceManifest","currentManifest","storedRisk"))r.remove(k);}return rows;}
 @Transactional public Object register(EhrActor a,Map<String,Object>b){allow(a,true);String record=text(b,"recordId"),key=text(b,"requestKey"),payload=hash(b);require(key.matches("[0-9a-fA-F-]{36}"),422,"请求键无效");ehr.profile(a,record,true);Map<String,Object> old=db.one("SELECT measurement_id,payload_digest FROM a_psych_measurements WHERE scope_code=? AND data_mode=? AND request_key=?",a.scope,a.mode,key);if(old!=null){require(payload.equals(old.get("payload_digest")),409,"请求键内容冲突");return map("id",old.get("measurement_id"),"replayed",true);}String category=text(b,"category"),instrument=text(b,"instrument").trim(),note=text(b,"note").trim(),description=text(b,"sourceDescription").trim(),when=text(b,"measuredAt");require(FACTORS.contains(category),422,"评估项目无效");require(!instrument.isEmpty()&&instrument.length()<=120&&!note.isEmpty()&&note.length()<=3000&&!description.isEmpty()&&description.length()<=1000,422,"请填写真实量表名称、结果说明及来源依据");try{LocalDateTime time=LocalDateTime.parse(when);require(time.getYear()>=1900&&!time.isAfter(LocalDateTime.now().plusMinutes(5)),422,"测评时间无效");}catch(java.time.format.DateTimeParseException e){throw new EhrException(422,"测评时间格式无效");}for(String k:Arrays.asList("score","maxScore")){Object v=b.get(k);require(v==null||v instanceof Number&&Double.isFinite(((Number)v).doubleValue())&&((Number)v).doubleValue()>=0&&((Number)v).doubleValue()<=10000,422,"分数应为0至10000的有效数值或留空");}if(b.get("score")!=null&&b.get("maxScore")!=null)require(((Number)b.get("score")).doubleValue()<=((Number)b.get("maxScore")).doubleValue(),422,"总分不能大于量表满分");require(Boolean.TRUE.equals(b.get("sourceVerified")),422,"请确认来源真实且有权登记");String id=id();db.insert("a_psych_measurements",map("measurement_id",id,"scope_code",a.scope,"data_mode",a.mode,"record_id",record,"category",category,"instrument",instrument,"total_score",b.get("score"),"max_score",b.get("maxScore"),"measured_at",when.replace('T',' '),"result_note",note,"source_description",description,"recorded_by",a.user,"request_key",key,"payload_digest",payload,"created_at",now()));ehr.audit(a,record,null,null,"psych_measurement_registered","已登记有来源的心理测评，未自动判断心理疾病或风险等级");return map("id",id);}
 public Map<String,Object> list(EhrActor a,Map<String,String>q){allow(a,false);List<Map<String,Object>> all=rows(a,0),people=new ArrayList<>();Set<String>orgs=new TreeSet<>(),teams=new TreeSet<>(),allowed=new HashSet<>();String category=q.getOrDefault("category","");require(category.isEmpty()||FACTORS.contains(category),422,"测评类别无效");String period=q.getOrDefault("period","12");require(Arrays.asList("12","24","all").contains(period),422,"时间范围无效");String search=q.getOrDefault("search","").trim();for(Map<String,Object>r:all){orgs.add(str(r.get("organization")));teams.add(str(r.get("team")));boolean match=search.isEmpty()||str(r.get("name")).contains(search)||str(r.get("code")).contains(search);for(String k:Arrays.asList("organization","team","riskLevel")){String value=q.getOrDefault(k,"");if(!value.isEmpty()&&!(k.equals("riskLevel")&&value.equals("elevated")?Arrays.asList("high","critical").contains(r.get(k)):value.equals(r.get(k))))match=false;}if(match){people.add(r);allowed.add(str(r.get("id")));}}
 List<Map<String,Object>> measures=db.all("SELECT m.measurement_id id,m.record_id recordId,m.category,m.instrument,m.total_score score,m.max_score maxScore,CAST(m.measured_at AS CHAR) measuredAt,m.result_note note,m.source_description sourceDescription,m.recorded_by recordedBy,p.employee_name name,p.employee_no code,p.organization_name organization,p.team_name team FROM a_psych_measurements m JOIN a_health_records r ON r.record_id=m.record_id AND r.scope_code=m.scope_code AND r.data_mode=m.data_mode JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode WHERE m.scope_code=? AND m.data_mode=? AND p.deleted_at IS NULL ORDER BY m.measured_at DESC,m.measurement_id DESC",a.scope,a.mode);LocalDate today=LocalDate.now(),cutoff=period.equals("all")?LocalDate.of(1900,1,1):today.minusMonths(Integer.parseInt(period));List<Map<String,Object>> records=new ArrayList<>();Map<String,Map<String,Object>> byId=new HashMap<>();for(Map<String,Object>p:people)byId.put(str(p.get("id")),p);Set<String>participants=new HashSet<>();Map<String,Object> composition=new LinkedHashMap<>();for(String f:FACTORS)composition.put(f,0);int monthCompleted=0;String selected=q.getOrDefault("record","");for(Map<String,Object>m:measures){String record=str(m.get("recordId"));if(!allowed.contains(record)||!category.isEmpty()&&!category.equals(m.get("category"))||LocalDate.parse(str(m.get("measuredAt")).substring(0,10)).isBefore(cutoff))continue;participants.add(record);Map<String,Object>p=byId.get(record);p.put("participated",true);if(str(m.get("measuredAt")).startsWith(today.toString().substring(0,7))){monthCompleted++;String f=str(m.get("category"));composition.put(f,num(composition.get(f))+1);}Map<?,?> domain=(Map<?,?>)((Map<?,?>)p.get("domains")).get(m.get("category"));m.put("riskLevel",domain==null?"unknown":domain.get("level"));m.put("state",p.get("state"));m.put("taskId",p.get("taskId"));m.put("assessmentYear",p.get("assessmentYear"));if(selected.isEmpty()||selected.equals(record))records.add(m);}
 if(!category.isEmpty()){people.removeIf(p->!Boolean.TRUE.equals(p.get("participated")));allowed.retainAll(participants);}Map<String,Object>counts=map("participants",participants.size(),"monthCompleted",monthCompleted,"highAttention",0,"followups",0,"completionRate",null,"confirmed",0,"low",0,"medium",0,"high",0,"critical",0);List<Map<String,Object>> alerts=new ArrayList<>();for(Map<String,Object>p:people){if("confirmed".equals(p.get("state"))){counts.put("confirmed",num(counts.get("confirmed"))+1);String level=str(p.get("riskLevel"));counts.put(level,num(counts.get(level))+1);if(Arrays.asList("high","critical").contains(level)){counts.put("highAttention",num(counts.get("highAttention"))+1);alerts.add(p);}}}for(Map<String,Object>f:db.all("SELECT record_id FROM a_digital_worker_tasks WHERE scope_code=? AND data_mode=? AND worker_id='care' AND title LIKE '心理随访:%' AND task_status IN ('queued','in_progress','pending_review')",a.scope,a.mode))if(allowed.contains(str(f.get("record_id"))))counts.put("followups",num(counts.get("followups"))+1);
 int questionnaireAssigned=0,questionnaireCompleted=0;for(Map<String,Object>m:db.all("SELECT x.record_id recordId,COUNT(*) assigned,SUM(r.response_id IS NOT NULL AND r.review_state<>'rejected') completed FROM a_questionnaire_assignments x JOIN a_questionnaire_releases l ON l.release_id=x.release_id AND l.scope_code=x.scope_code AND l.data_mode=x.data_mode JOIN a_questionnaires q ON q.questionnaire_id=l.questionnaire_id AND q.scope_code=l.scope_code AND q.data_mode=l.data_mode LEFT JOIN a_questionnaire_responses r ON r.assignment_id=x.assignment_id AND r.scope_code=x.scope_code AND r.data_mode=x.data_mode WHERE x.scope_code=? AND x.data_mode=? AND q.category IN ('psychological','stress','sleep') GROUP BY x.record_id",a.scope,a.mode))if(allowed.contains(str(m.get("recordId")))){questionnaireAssigned+=num(m.get("assigned"));questionnaireCompleted+=num(m.get("completed"));}if(questionnaireAssigned>0)counts.put("completionRate",Math.round(questionnaireCompleted*1000.0/questionnaireAssigned)/10.0);
 List<Map<String,Object>> history=db.all("SELECT record_id recordId,risk_level riskLevel,CAST(DATE(CONVERT_TZ(reviewed_at,'+00:00','+08:00')) AS CHAR) day FROM a_psych_assessment_tasks WHERE scope_code=? AND data_mode=? AND review_state='confirmed' ORDER BY reviewed_at,task_id",a.scope,a.mode);List<Object> trend=new ArrayList<>();for(int i=11;i>=0;i--){LocalDate month=today.withDayOfMonth(1).minusMonths(i),end=month.plusMonths(1);Map<String,String>last=new HashMap<>();for(Map<String,Object>h:history)if(allowed.contains(str(h.get("recordId")))&&LocalDate.parse(str(h.get("day"))).isBefore(end))last.put(str(h.get("recordId")),str(h.get("riskLevel")));int n=0;for(String level:last.values())if(Arrays.asList("medium","high","critical").contains(level))n++;trend.add(map("month",month.toString().substring(0,7),"count",n));}
 int page=bounded(q.get("page"),1,1,100000),limit=bounded(q.get("limit"),10,1,100),rpage=bounded(q.get("recordPage"),1,1,100000),rlimit=bounded(q.get("recordLimit"),10,1,100),from=Math.min(people.size(),(page-1)*limit),rf=Math.min(records.size(),(rpage-1)*rlimit);return map("items",people.subList(from,Math.min(from+limit,people.size())),"total",people.size(),"page",page,"limit",limit,"records",records.subList(rf,Math.min(rf+rlimit,records.size())),"recordTotal",records.size(),"recordPage",rpage,"recordLimit",rlimit,"counts",counts,"composition",composition,"trend",trend,"alerts",alerts.subList(0,Math.min(5,alerts.size())),"organizations",orgs,"teams",teams,"canReview",a.doctor,"candidateOnly",ehr.candidateOnly,"assessmentYear",today.getYear());}

 Map<String,Object> job(EhrActor a,String id,boolean lock){Map<String,Object> row=db.one("SELECT * FROM a_psych_assessment_tasks WHERE task_id=? AND scope_code=? AND data_mode=?",id,a.scope,a.mode);require(row!=null,404,"心理健康风险任务不存在或无权限");ehr.profile(a,str(row.get("record_id")),lock);if(lock)row=db.one("SELECT * FROM a_psych_assessment_tasks WHERE task_id=? AND scope_code=? AND data_mode=? FOR UPDATE",id,a.scope,a.mode);return row;}
 public Map<String,Object> detail(EhrActor a,String record,int year,String task){allow(a,false);Map<String,Object> facts=source(a,record),t=task==null||task.isEmpty()?db.one("SELECT * FROM a_psych_assessment_tasks WHERE scope_code=? AND data_mode=? AND record_id=? AND assessment_year=? ORDER BY created_at DESC,task_id DESC LIMIT 1",a.scope,a.mode,record,year):job(a,task,false);require(t==null||record.equals(t.get("record_id"))&&num(t.get("assessment_year"))==year,404,"任务不属于当前职工和年度");Map<String,Object> current=rules(a);return map("source",facts,"sourceDigest",sourceHash(facts),"job",t,"sourceChanged",t!=null&&!sourceHash(facts).equals(t.get("source_digest")),"rulesChanged",t!=null&&num(t.get("rules_version"))!=num(current.get("version")),"history",db.all("SELECT task_id id,ai_state aiState,review_state reviewState,risk_level riskLevel,created_at createdAt,reviewed_at reviewedAt FROM a_psych_assessment_tasks WHERE scope_code=? AND data_mode=? AND record_id=? AND assessment_year=? ORDER BY created_at DESC,task_id DESC LIMIT 30",a.scope,a.mode,record,year),"canReview",a.doctor,"candidateOnly",ehr.candidateOnly);}
 @Transactional public Map<String,Object> enqueue(EhrActor a,Map<String,Object> b){allow(a,true);require(Boolean.TRUE.equals(client.status().get("configured")),503,"独立AI服务尚未配置");int y=year(b.get("year"));String key=text(b,"requestKey");require(key.matches("[0-9a-fA-F-]{36}"),422,"请求键无效");Object raw=b.get("records");require(raw instanceof List&&!((List<?>)raw).isEmpty()&&((List<?>)raw).size()<=20,422,"每批请选择1至20名职工");String payload=hash(b);Map<String,Object> policy=settings.lock(a,"assess");List<Map<String,Object>> old=db.all("SELECT batch_id,payload_digest FROM a_psych_assessment_tasks WHERE scope_code=? AND data_mode=? AND request_key=?",a.scope,a.mode,key);if(!old.isEmpty()){require(payload.equals(old.get(0).get("payload_digest")),409,"请求键已用于不同内容");return map("batchId",old.get(0).get("batch_id"),"count",old.size(),"replayed",true);}settings.requireAi(policy);settings.admit(a,"assess","assessment",policy);require(db.count("SELECT COUNT(*) FROM a_psych_assessment_tasks WHERE scope_code=? AND data_mode=? AND ai_state IN ('queued','running')",a.scope,a.mode)+((List<?>)raw).size()<=num(policy.get("maxActiveTasks")),409,"心理健康风险任务队列已达配置上限");Set<String> ids=new TreeSet<>();for(Object v:(List<?>)raw){require(v instanceof String&&str(v).matches("[0-9a-fA-F-]{36}")&&ids.add(str(v)),422,"职工标识无效或重复");}Map<String,Object> rule=rules(a);String batch=id();for(String record:ids){ehr.profile(a,record,true);require(db.count("SELECT COUNT(*) FROM a_psych_assessment_tasks WHERE scope_code=? AND data_mode=? AND record_id=? AND assessment_year=? AND ai_state IN ('queued','running')",a.scope,a.mode,record,y)==0,409,"所选职工已有本年度分析排队或运行");Map<String,Object> facts=source(a,record);List<?> reports=(List<?>)facts.get("measurements");require(!reports.isEmpty(),422,"所选职工尚无已登记的心理测评结果，请先登记原始测评资料");require(ehr.encode(facts).length()<=1800000,422,"关联资料过多，请整理后再评估");String task=id();db.insert("a_psych_assessment_tasks",map("task_id",task,"batch_id",batch,"scope_code",a.scope,"data_mode",a.mode,"record_id",record,"assessment_year",y,"request_key",key,"payload_digest",payload,"source_digest",sourceHash(facts),"source_json",ehr.encode(facts),"profile_version",facts.get("rowVersion"),"report_manifest",manifest(a,record),"rules_version",rule.get("version"),"rules_json",ehr.encode(rule.get("document")),"ai_state","queued","requested_by",a.user,"created_at",now()));ehr.audit(a,record,null,null,"psych_assessment_enqueued","已排队心理健康风险辅助分析，年度"+y+"；不自动确认风险");}return map("batchId",batch,"count",ids.size());}
 @Transactional(isolation=Isolation.READ_COMMITTED) public Map<String,Object> claim(String mode){db.exec("UPDATE a_psych_assessment_tasks SET ai_state='failed',error_code='AI_LEASE_EXPIRED',finished_at=UTC_TIMESTAMP(6),lease_until=NULL,row_version=row_version+1 WHERE data_mode=? AND ai_state='running' AND lease_until<UTC_TIMESTAMP(6)",mode);Map<String,Object> t=db.one("SELECT * FROM a_psych_assessment_tasks WHERE data_mode=? AND ai_state='queued' ORDER BY created_at,task_id LIMIT 1 FOR UPDATE",mode);if(t==null)return null;db.exec("UPDATE a_psych_assessment_tasks SET ai_state='running',lease_until=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 20 MINUTE),row_version=row_version+1 WHERE task_id=?",t.get("task_id"));t.put("row_version",num(t.get("row_version"))+1);return t;}
 EhrActor workerActor(Map<String,Object> t){String scope=str(t.get("scope_code"));require(scope.startsWith("org:")&&db.count("SELECT COUNT(*) FROM yh_user_reginfo WHERE user_code=? AND lock_flag=2 AND User_Type=4 AND CONCAT('org:',Org_Code)=?",t.get("requested_by"),scope)>0,403,"AI_ACCESS_REVOKED");return new EhrActor(str(t.get("requested_by")),scope.substring(4),str(t.get("data_mode")),true,false);}
 void verify(EhrActor a,Map<String,Object> t){require(sourceHash(source(a,str(t.get("record_id")))).equals(t.get("source_digest")),409,"AI_SOURCE_CHANGED");require(num(rules(a).get("version"))==num(t.get("rules_version")),409,"AI_RULES_CHANGED");}
 public Map<String,Object> modelInput(Map<String,Object> t){EhrActor a=workerActor(t);verify(a,t);settings.requireAi(settings.get(a,"assess"));Map<String,Object> rules=(Map<String,Object>)ehr.decode(t.get("rules_json"));return map("worker_id","assess","task_type","psychological_assessment","title","心理健康风险辅助评估 · "+t.get("assessment_year"),"instructions",rules.get("instructions"),"archive_context",map("assessmentYear",t.get("assessment_year"),"measurements",((Map<?,?>)ehr.decode(t.get("source_json"))).get("measurements"),"rules",rules,"assessmentRules",((Map<?,?>)ehr.decode(t.get("source_json"))).get("assessmentRules")));}
 @Transactional public void finish(Map<String,Object> claimed,String output,String failure){String error=failure;try{EhrActor a=workerActor(claimed);ehr.profile(a,str(claimed.get("record_id")),true);verify(a,claimed);settings.requireAi(settings.get(a,"assess"));}catch(EhrException e){error=e.getMessage().matches("[A-Z0-9_]{1,80}")?e.getMessage():"AI_ACCESS_OR_SOURCE_UNAVAILABLE";}Map<String,Object> t=db.one("SELECT * FROM a_psych_assessment_tasks WHERE task_id=? FOR UPDATE",claimed.get("task_id"));if(t==null||!"running".equals(t.get("ai_state"))||num(t.get("row_version"))!=num(claimed.get("row_version")))return;boolean ok=error==null&&output!=null&&!output.trim().isEmpty();db.exec("UPDATE a_psych_assessment_tasks SET ai_state=?,output_text=?,error_code=?,finished_at=UTC_TIMESTAMP(6),lease_until=NULL,row_version=row_version+1 WHERE task_id=?",ok?"completed":"failed",ok?output:null,ok?null:error==null?"AI_EMPTY":error,t.get("task_id"));}
 public List<Map<String,Object>> tasks(EhrActor a){allow(a,false);return db.all("SELECT t.batch_id batchId,t.task_id id,t.record_id recordId,t.assessment_year year,t.ai_state aiState,t.review_state reviewState,t.error_code errorCode,t.created_at createdAt,t.row_version version,p.employee_name name,p.employee_no code FROM a_psych_assessment_tasks t JOIN a_health_records r ON r.record_id=t.record_id AND r.scope_code=t.scope_code AND r.data_mode=t.data_mode JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode WHERE t.scope_code=? AND t.data_mode=? AND p.deleted_at IS NULL ORDER BY t.created_at DESC,t.task_id DESC LIMIT 100",a.scope,a.mode);}
 @Transactional public Object action(EhrActor a,String task,Map<String,Object> b){allow(a,true);Map<String,Object> t=job(a,task,true);String key=text(b,"requestKey"),action=text(b,"action"),note=text(b,"note").trim(),payload=hash(b);require(key.matches("[0-9a-fA-F-]{36}")&&Arrays.asList("cancel","review").contains(action),422,"操作或请求键无效");Map<String,Object> old=db.one("SELECT payload_digest FROM a_psych_assessment_events WHERE task_id=? AND request_key=?",task,key);if(old!=null){require(payload.equals(old.get("payload_digest")),409,"操作键内容冲突");return map("replayed",true);}require(!note.isEmpty()&&note.length()<=3000,422,"请填写处理依据，最多3000字");require(b.get("version") instanceof Number&&num(b.get("version"))==num(t.get("row_version")),409,"任务版本已更新，请刷新");String record=str(t.get("record_id"));if(action.equals("cancel")){require(Arrays.asList("queued","running").contains(t.get("ai_state")),409,"当前任务不能取消");db.exec("UPDATE a_psych_assessment_tasks SET ai_state='cancelled',finished_at=UTC_TIMESTAMP(6),lease_until=NULL,row_version=row_version+1 WHERE task_id=?",task);}else{require(!ehr.candidateOnly,403,"当前环境不允许审核确认");require("completed".equals(t.get("ai_state"))&&"pending".equals(t.get("review_state")),409,"请先完成AI辅助分析或重新发起评估");require(task.equals(db.one("SELECT task_id FROM a_psych_assessment_tasks WHERE scope_code=? AND data_mode=? AND record_id=? AND assessment_year=? ORDER BY created_at DESC,task_id DESC LIMIT 1",a.scope,a.mode,record,t.get("assessment_year")).get("task_id")),409,"请审核本年度最新任务");verify(a,t);require(Boolean.TRUE.equals(b.get("identityVerified"))&&Boolean.TRUE.equals(b.get("sourceVerified")),422,"请核对职工身份、报告原件及生活习惯与病史资料");String risk=text(b,"riskLevel");require(Arrays.asList("low","medium","high","critical").contains(risk),422,"请由医生核定综合心理健康风险");Object raw=b.get("domains");require(raw instanceof Map&&((Map<?,?>)raw).keySet().equals(new HashSet<>(FACTORS)),422,"请核对五类分项风险");Map<String,Object> domains=new LinkedHashMap<>();for(String f:FACTORS){Object v=((Map<?,?>)raw).get(f);require(v instanceof Map,422,"风险格式无效");String level=str(((Map<?,?>)v).get("level")),basis=str(((Map<?,?>)v).get("basis")).trim();require(Arrays.asList("unknown","low","medium","high","critical").contains(level)&&basis.length()<=1500&&(level.equals("unknown")||!basis.isEmpty()),422,"分项风险需明确等级与依据");domains.put(f,map("level",level,"basis",basis));}Map<String,Object> facts=source(a,record);String assessment=null;db.exec("UPDATE a_psych_assessment_tasks SET review_state='confirmed',risk_level=?,domain_json=?,reviewer=?,review_note=?,reviewed_at=UTC_TIMESTAMP(6),assessment_id=?,row_version=row_version+1 WHERE task_id=?",risk,ehr.encode(domains),a.user,note,assessment,task);}db.insert("a_psych_assessment_events",map("event_id",id(),"task_id",task,"actor",a.user,"action",action,"note",note,"request_key",key,"payload_digest",payload,"created_at",now()));ehr.audit(a,record,null,null,"psych_assessment_"+action,note);return map("id",task,"action",action);}
}
